/* Rental checkout, private receipts, customer tracking */
(()=>{if(location.pathname.startsWith('/cms'))return;const SB='https://xleceiffuopioeguniwj.supabase.co',KEY='sb_publishable_POksYryhG_mkFbs7N0fjKQ_4dUim7Ex';const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),M=n=>'Rp'+Number(n||0).toLocaleString('id-ID'),banks=()=> (window.RENTCAM_CMS_CONFIG?.payment?.bankAccounts||[]).filter(b=>b.active!==false);async function rpc(name,data){const r=await fetch(SB+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.message||'Gagal memproses. Coba lagi.');return j}async function upload(file){if(!file||!file.size)throw Error('Pilih bukti transfer.');if(file.size>5242880||!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw Error('Gunakan JPG, PNG, WEBP atau PDF maksimal 5 MB.');const token=await rpc('rentcam_checkout_upload_token',{}),path=token+'/'+crypto.randomUUID()+'.'+({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'}[file.type]);const r=await fetch(SB+'/storage/v1/object/rental-receipts/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':file.type},body:file});if(!r.ok)throw Error('Upload bukti gagal. Coba lagi.');return path}const bankFields=()=>`<label>Rekening tujuan<select name="bank"><option value="">Pilih rekening</option>${banks().map(b=>`<option value="${E(b.id)}">${E(b.bank)} · ${E(b.holder)}</option>`).join('')}</select></label><p data-bank-info>${banks().length?'Pilih rekening untuk melihat nomor tujuan.':'Rekening belum diatur. Pesanan tetap dapat diajukan untuk konfirmasi pembayaran.'}</p><label>Nominal transfer<input name="amount" type="number" min="1" step="1" placeholder="Nominal yang ditransfer"></label><label>Bukti transfer (JPG, PNG, WEBP atau PDF, maks. 5 MB)<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label>`;const today=()=>new Date().toLocaleDateString('sv-SE');function mount(){if(location.pathname==='/pesanan'){portal();return}if(location.pathname!=='/cart')return;const host=document.querySelector('#app .summary');if(!host||host.querySelector('#rentcamOrderForm'))return;host.querySelector('.wide')?.remove();host.insertAdjacentHTML('beforeend',`<form id="rentcamOrderForm" class="rc-form"><h3>Pemesanan rental</h3><label>Nama lengkap<input name="name" required minlength="2" maxlength="120" autocomplete="name"></label><label>WhatsApp<input name="phone" type="tel" required autocomplete="tel"></label><label>Email (opsional)<input name="email" type="email"></label><div class="rc-grid"><label>Mulai sewa<input name="start" type="date" min="${today()}" value="${today()}" required></label><label>Selesai sewa<input name="end" type="date" min="${today()}" value="${today()}" required></label></div><h4>Pengambilan & pengembalian</h4><label>Pengambilan<select name="mode"><option value="self_pickup">Ambil sendiri</option><option value="delivery">Diantar ke alamat</option></select></label><label data-delivery hidden>Jam diantar<input name="deliver_at" type="datetime-local"></label><label>Pengembalian<select name="return_mode"><option value="self_return">Kembalikan sendiri</option><option value="collect">Dijemput dari alamat</option></select></label><label data-collect hidden>Jam dijemput<input name="collect_at" type="datetime-local"></label><label data-address hidden>Alamat lengkap<textarea name="address" maxlength="500"></textarea></label><h4>Pembayaran transfer</h4>${bankFields()}<p>Bukti transfer akan diperiksa admin. Rental disetujui setelah pembayaran terverifikasi dan stok tersedia. Jadwal serta biaya antar–jemput dikonfirmasi tim.</p><label>Catatan<textarea name="notes" maxlength="2000"></textarea></label><p data-estimate></p><button type="submit" class="wide">Kirim pesanan</button><p role="status" data-msg></p></form>`);update(host.querySelector('form'))}function update(f){if(f.elements.mode){const d=f.elements.mode.value==='delivery',c=f.elements.return_mode.value==='collect';for(const [sel,field,on]of [['[data-delivery]','deliver_at',d],['[data-collect]','collect_at',c],['[data-address]','address',d||c]]){f.querySelector(sel).hidden=!on;f.elements[field].required=on}f.elements.end.min=f.elements.start.value;const days=Math.round((new Date(f.elements.end.value)-new Date(f.elements.start.value))/86400000)+1;f.querySelector('[data-estimate]').textContent=days>0?'Durasi sewa '+days+' hari. Total dihitung berdasarkan harga produk dan diskon aktif.':'Periksa tanggal selesai.'}const b=banks().find(b=>b.id===f.elements.bank.value);f.querySelector('[data-bank-info]').textContent=b?b.bank+' · '+b.number+' · a.n. '+b.holder:banks().length?'Pilih rekening tujuan.':'Rekening belum diatur; tim akan mengonfirmasi pembayaran.'}document.addEventListener('change',e=>{const f=e.target.closest('.rc-form');if(f)update(f)});document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('#rentcamOrderForm,#rcProofForm'))return;e.preventDefault();const btn=f.querySelector('[type=submit]'),msg=f.querySelector('[data-msg]');if(btn.disabled)return;btn.disabled=true;msg.textContent='Memproses...';try{const x=Object.fromEntries(new FormData(f)),file=f.elements.receipt.files[0];if(file&&(!x.bank||Number(x.amount)<=0))throw Error('Pilih rekening dan isi nominal transfer.');if(f.id==='rcProofForm'){if(!x.bank||!file||Number(x.amount)<=0)throw Error('Lengkapi rekening, nominal dan bukti transfer.');const [id,token]=location.hash.slice(1).split(':');const sig=JSON.stringify([id,x.bank,x.amount,file.name,file.size,file.lastModified]);let pending=JSON.parse(sessionStorage.getItem('rc_proof_retry')||'null');if(pending?.sig!==sig){pending={sig,path:await upload(file)};sessionStorage.setItem('rc_proof_retry',JSON.stringify(pending))}await rpc('rentcam_customer_proof',{p_order:id,p_customer:token,p_path:pending.path,p_bank:x.bank,p_amount:Number(x.amount)});sessionStorage.removeItem('rc_proof_retry');await portal(true);return}const phone=x.phone.replace(/[^0-9+]/g,'');if(!/^\+?[0-9]{8,16}$/.test(phone))throw Error('Isi WhatsApp yang valid.');const items=JSON.parse(localStorage.getItem('bsm_cart_cm')||'[]');if(!items.length)throw Error('Keranjang kosong.');if(x.end<x.start)throw Error('Tanggal selesai tidak boleh sebelum mulai.');const base={p_name:x.name.trim(),p_phone:phone,p_email:x.email.trim(),p_start:x.start,p_end:x.end,p_notes:x.notes.trim(),p_items:items.map(i=>({id:i.id,q:i.q})),p_details:{delivery:{mode:x.mode,return_mode:x.return_mode,address:x.address,deliver_at:x.mode==='delivery'?new Date(x.deliver_at).toISOString():null,collect_at:x.return_mode==='collect'?new Date(x.collect_at).toISOString():null},bank_id:x.bank,transfer_amount:Number(x.amount)||null}};const sig=JSON.stringify([base,file&&[file.name,file.size,file.lastModified]]);let retry=JSON.parse(sessionStorage.getItem('rentcam_order_retry')||'null');if(retry?.signature!==sig||!retry.payload){base.p_id=crypto.randomUUID();base.p_details.customer_token=crypto.randomUUID();if(file)base.p_details.receipt_path=await upload(file);retry={signature:sig,payload:base};sessionStorage.setItem('rentcam_order_retry',JSON.stringify(retry))}const order=await rpc('rentcam_checkout',retry.payload),link='/pesanan#'+order.id+':'+order.customer_token;sessionStorage.removeItem('rentcam_order_retry');localStorage.setItem('bsm_cart_cm','[]');try{cart.splice(0,cart.length);save()}catch{}localStorage.setItem('rentcam_last_order',link);f.innerHTML=`<h3>Pesanan berhasil dikirim</h3><p>${E(order.order_number)} · ${M(order.total)}</p><p>${file?'Bukti transfer menunggu verifikasi admin.':'Menunggu pembayaran dan konfirmasi admin.'}</p><a class="wide" href="${E(link)}">Lihat status & upload bukti</a><p>Simpan tautan ini untuk memantau pesanan Anda.</p>`}catch(err){msg.textContent=err.message;btn.disabled=false}});let portalBusy=false,portalDone='';async function portal(force=false){const h=location.hash;if(portalBusy||(!force&&portalDone===h))return;const root=document.querySelector('#app');if(!root)return;portalBusy=true;portalDone=h;try{const [id,token]=h.slice(1).split(':');if(!id||!token){root.innerHTML=`<section class="rc-portal"><h1>Status pesanan</h1><p>Gunakan tautan pesanan yang diberikan setelah checkout.</p>${localStorage.getItem('rentcam_last_order')?`<a href="${E(localStorage.getItem('rentcam_last_order'))}">Buka pesanan terakhir</a>`:''}</section>`;return}const o=await rpc('rentcam_customer_order',{p_id:id,p_token:token});if(!o)throw Error('Pesanan tidak ditemukan. Periksa tautan Anda.');root.innerHTML=`<section class="rc-portal"><a href="/">← Home</a><h1>${E(o.order_number)}</h1><p>${E(o.customer_name)} · ${E(o.start_date)} — ${E(o.end_date)}</p><p>Pembayaran: <strong>${E(status(o.payment_status))}</strong> · Rental: <strong>${E(status(o.rental_status))}</strong></p>${o.items.map(i=>`<p>${E(i.name)} × ${i.quantity} <strong>${M(i.amount)}</strong></p>`).join('')}<hr><p>Total <strong>${M(o.total)}</strong></p><p>Terverifikasi <strong>${M(o.paid_amount)}</strong> · Sisa ${M(Math.max(0,o.total-o.paid_amount))}</p>${o.delivery?.address?`<p>Alamat: ${E(o.delivery.address)}</p>`:''}${['deliver_at','collect_at'].map(k=>o.delivery?.[k]?`<p>${k==='deliver_at'?'Diantar':'Dijemput'}: ${E(new Date(o.delivery[k]).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}))} WIB</p>`:'').join('')}<h3>Bukti pembayaran</h3>${(o.proofs||[]).map(p=>`<p>${M(p.amount)} · ${E(status(p.status))} ${E(p.note)}</p>`).join('')||'<p>Belum ada bukti.</p>'}<button id="rcRefresh">Perbarui status</button>${!['paid'].includes(o.payment_status)&&o.rental_status!=='cancelled'?`<form class="rc-form" id="rcProofForm"><h3>Upload bukti transfer</h3>${bankFields()}<button type="submit">Kirim bukti transfer</button><p data-msg role="status"></p></form>`:''}</section>`;root.querySelector('#rcRefresh').onclick=()=>portal(true)}catch(e){root.innerHTML='<section class="rc-portal"><p>'+E(e.message)+'</p></section>';portalDone=''}finally{portalBusy=false}}function status(s){return ({unpaid:'Belum bayar',pending:'Menunggu verifikasi',partial:'Dibayar sebagian',paid:'Lunas',rejected:'Ditolak',requested:'Menunggu persetujuan',approved:'Disetujui',rented:'Sedang disewa',returned:'Dikembalikan',cancelled:'Dibatalkan'})[s]||s}const st=document.createElement('style');st.textContent='.rc-form{margin-top:20px;padding-top:16px;border-top:1px solid #eee}.rc-form label{display:block;margin:12px 0;font-size:13px;font-weight:600}.rc-form input,.rc-form select,.rc-form textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;border:1px solid #ddd;border-radius:10px;padding:12px;font:inherit;font-size:16px;background:white;color:#111}.rc-form p{font-size:13px;line-height:1.6;color:#666}.rc-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.rc-form [hidden]{display:none}.rc-portal{max-width:760px;margin:35px auto;padding:20px;line-height:1.8}.rc-portal button,.rc-form button{padding:13px 18px;background:#111;color:white;border:0;border-radius:10px}.rc-form button:disabled{opacity:.5}';document.head.append(st);let queued=false;const run=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;mount()})};new MutationObserver(run).observe(document.querySelector('#app')||document.body,{childList:true,subtree:true});window.addEventListener('hashchange',()=>portal(true));document.addEventListener('rentcam-route-change',run);document.addEventListener('rentcam-cms-updated',run);run()})();
